import time
from collections import defaultdict
import statistics

class TimeseriesRollupEngine:
    """
    An in-memory timeseries rollup engine supporting recording metrics with timestamps
    and querying rolled-up aggregations over specified time windows.
    """
    def __init__(self):
        # Stores data as: self._store[metric] = list of tuples: (timestamp, value)
        self._store = defaultdict(list)

    def record(self, metric: str, value: float, timestamp: float = None) -> None:
        """
        Record a metric value at a given timestamp.
        If timestamp is not provided, uses the current epoch time.
        """
        if timestamp is None:
            timestamp = time.time()

        self._store[metric].append((timestamp, float(value)))
        # Keep records sorted by timestamp to enable efficient window slicing
        self._store[metric].sort(key=lambda x: x[0])

    def query_rollup(self, metric: str, window_sec: float, agg_func: str) -> float:
        """
        Query the rollup aggregation for a given metric over a time window (in seconds)
        ending at the current time (or the latest timestamp recorded for the metric).

        Supported aggregation functions ('agg_func'):
        - 'sum'
        - 'avg', 'mean'
        - 'min'
        - 'max'
        - 'count'
        - 'p95' (95th percentile)
        """
        if metric not in self._store or not self._store[metric]:
            return 0.0 if agg_func in ('sum', 'count') else 0.0

        records = self._store[metric]
        latest_timestamp = records[-1][0]
        cutoff_time = latest_timestamp - window_sec

        # Filter values within the time window
        window_values = [val for ts, val in records if ts >= cutoff_time]

        if not window_values:
            return 0.0

        agg_lower = agg_func.lower()
        if agg_lower == 'sum':
            return sum(window_values)
        elif agg_lower in ('avg', 'mean'):
            return statistics.mean(window_values)
        elif agg_lower == 'min':
            return min(window_values)
        elif agg_lower == 'max':
            return max(window_values)
        elif agg_lower == 'count':
            return float(len(window_values))
        elif agg_lower == 'p95':
            sorted_vals = sorted(window_values)
            index = int(0.95 * (len(sorted_vals) - 1))
            return sorted_vals[index]
        else:
            raise ValueError(f"Unsupported aggregation function: {agg_func}")
